import React, { useState, useEffect } from 'react';
import { Message, KnowledgeItem, EmotionType } from '../types';

interface ChatMessageProps {
  message: Message;
  knowledgeSources?: KnowledgeItem[];
  onSimilarQuestionClick?: (question: string) => void;
}

const emotionIcons: Record<EmotionType, string> = {
  happy: '😊',
  sad: '😢',
  anxious: '😰',
  angry: '😠',
  lonely: '🥺',
  neutral: '😌',
  hopeful: '🌟',
  confused: '😕',
  frustrated: '😤',
  guilty: '😔',
  shameful: '😳',
  proud: '😊'
};

const emotionLabels: Record<EmotionType, string> = {
  happy: '开心',
  sad: '低落',
  anxious: '焦虑',
  angry: '愤怒',
  lonely: '孤独',
  neutral: '平稳',
  hopeful: '充满希望',
  confused: '迷茫困惑',
  frustrated: '挫败',
  guilty: '内疚',
  shameful: '羞愧',
  proud: '自豪'
};

export const ChatMessage: React.FC<ChatMessageProps> = ({
  message,
  knowledgeSources,
  onSimilarQuestionClick
}) => {
  const [displayedContent, setDisplayedContent] = useState('');
  const [isTyping, setIsTyping] = useState(true);

  useEffect(() => {
    if (message.type === 'bot') {
      setDisplayedContent('');
      setIsTyping(true);
      let index = 0;
      const content = message.content;
      const interval = setInterval(() => {
        if (index < content.length) {
          setDisplayedContent(content.slice(0, index + 1));
          index++;
        } else {
          clearInterval(interval);
          setIsTyping(false);
        }
      }, 30);
      return () => clearInterval(interval);
    } else {
      setDisplayedContent(message.content);
      setIsTyping(false);
    }
  }, [message.content, message.type]);

  return (
    <div className={`message-wrapper ${message.type}`}>
      <div className="message-avatar">
        {message.type === 'user' ? (
          <div className="avatar user-avatar">👤</div>
        ) : (
          <div className="avatar bot-avatar" style={{ backgroundColor: message.emotionStyle?.color || '#607D8B' }}>
            🧠
          </div>
        )}
      </div>

      <div className="message-content-wrapper">
        {message.type === 'bot' && message.emotion && (
          <div className="emotion-tag" style={{ color: message.emotionStyle?.color }}>
            {emotionIcons[message.emotion.emotion]} {emotionLabels[message.emotion.emotion]}
          </div>
        )}

        <div className={`message-bubble ${message.type}`}>
          <div className="message-text">
            {displayedContent}
            {isTyping && <span className="typing-cursor">|</span>}
          </div>

          {message.timestamp && (
            <div className="message-timestamp">{message.timestamp}</div>
          )}

          {message.risk && (message.risk.level === 'high' || message.risk.level === 'critical') && (
            <div className={`risk-warning ${message.risk.level}`}>
              <div className="warning-icon">⚠️</div>
              <div className="warning-content">
                <div className="warning-title">危机预警</div>
                <div className="warning-message">{message.risk.warningMessage}</div>
                <div className="warning-hotline">{message.risk.hotline}</div>
              </div>
            </div>
          )}

          {knowledgeSources && knowledgeSources.length > 0 && (
            <div className="knowledge-sources">
              <h4>📚 参考知识</h4>
              {knowledgeSources.map((item, idx) => (
                <div key={idx} className="knowledge-item">
                  <div className="knowledge-question">{item.question}</div>
                  <div className="knowledge-answer">{item.answer}</div>
                </div>
              ))}
            </div>
          )}

          {message.similarQuestions && message.similarQuestions.length > 0 && (
            <div className="similar-questions">
              <h4>💡 相似问题</h4>
              {message.similarQuestions.map((item, idx) => (
                <div
                  key={idx}
                  className="similar-question-item"
                  onClick={() => onSimilarQuestionClick?.(item.question)}
                >
                  <div className="question-text">{item.question}</div>
                  <div className="keywords">{item.keywords}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
